ST.xhtml:p:
(*自动对边*)
rTrigMove1( CLK := (g_bAutoParalleEnableM));
rTrigMove2( CLK := (g_bAutoParalleCloseM));
rTrigMove3( CLK := (g_biIntPut_FindEage));
rTrigMove4( CLK := (g_bFindEageM));
rTrigMove5( CLK := (g_bCapacitanceDetection));
rTrigMove6( CLK := (g_bCapacitorCheckStart));
rTrigMove7( CLK := (g_bCapacitorCheckEnd));
fTrigMove4( CLK := (g_biIntPut_FindEage));

rTrigMovePause( CLK := (g_bPlcPauseBuffer));



(*m代码控制g_boFindEage输出*)
IF rTrigMove3.Q THEN
  g_boFindEage := TRUE;
END_IF;

IF fTrigMove4.Q OR rTrigMove4.Q THEN
  g_bFindEageM := FALSE;
  g_boFindEage := FALSE;
END_IF;

IF rTrigMove1.Q THEN
  nMoveState := 9;
  (*初始化*)
  g_boFindEage := FALSE;
  fYStartePos:=g_fCurrentCoordYBuffer;
  g_foKuXunNoSuitable:=0.0;
  g_bAutoParalleEnableM := FALSE;
  bAutoParalleDone := FALSE;
END_IF;

IF rTrigMove2.Q THEN
  g_bAutoParalleCloseM := FALSE;
  IF M.PARAMETER_P[163]=0.0 THEN
    bAutoParalleDone := TRUE;
    nCloseParalleState := 10;
  ELSIF M.PARAMETER_P[163] =1.0 THEN
    dAutoParalleXmachineCoordinate1 := g_fYOverShootPosition;
    nZSensorValue1 :=UDINT_TO_LREAL(g_niZSensorValue);
    M.ENABLE[163] := 0;
  ELSIF M.PARAMETER_P[163] =2.0 THEN
    dAutoParalleXmachineCoordinate2 := g_fYOverShootPosition;
    nZSensorValue2 := UDINT_TO_LREAL(g_niZSensorValue);
    M.ENABLE[163] := 0;
  ELSIF M.PARAMETER_P[163] = 3.0 THEN
    dAutoParalleNumber := dAutoParalleNumber + 1.0;
    M.ENABLE[163] := 0;
  ELSIF M.PARAMETER_P[163] = 4.0 THEN
    dAutoParalleNumber := 0.0;
    M.ENABLE[163] := 0;
  END_IF; 
END_IF;

IF rTrigMove5.Q THEN
  g_bCapacitanceDetection := FALSE;
  IF bOpenEdgCapacitanceAlarm = FALSE THEN
    g_bEdgCapacitanceAlarm := FALSE;
  ELSIF (g_nAutoParalleType=0 AND g_fZAxisHeight > (g_fParalleBorderHeightM+g_fParalleZFollowHeightM) ) OR (g_nAutoParalleType=1 AND g_bAutoParalleInfraedSensor=FALSE) THEN
    g_bEdgCapacitanceAlarm := TRUE;
  ELSE
    g_bEdgCapacitanceAlarm := FALSE;
  END_IF;
  M.ENABLE[324] := 0;
END_IF;

IF rTrigMove6.Q THEN
  g_bCapacitorCheckStart := FALSE;
  IF bOpenEdgCapacitanceAlarm AND g_nAutoParalleType=0 THEN
    Ton_Alarm(IN := FALSE);
    nCapacitorCheckState := 10;
  ELSE
    nCapacitorCheckState := 0;  
  END_IF;
  M.ENABLE[324] := 0;
END_IF;

IF rTrigMove7.Q THEN
  g_bCapacitorCheckEnd := FALSE;
  nCapacitorCheckState := 0;  
  M.ENABLE[324] := 0; 
END_IF;


CASE nMoveState OF
  0:(*空闲*)
    nMoveState := 0;
  9:
  delay_ton(IN := TRUE,PT := T#50ms);
  IF delay_ton.Q THEN
    nMoveState := 10;
    delay_ton(IN := FALSE);
    IF g_bOpenFollowDownLimitVel THEN
      g_ZFollowIn.DISABLENEGATIVE := TRUE;
    END_IF;
  END_IF;
  10:(*探边*)
    IF g_nPlcState = 1 THEN
      (*g_nAutoParalleType=0 当前高度大于阶跃高度+随动设置高度（寻到边）*)
      (*g_nAutoParalleType=1 红外传感器拿到低电平就寻到边，取下降沿可能有风险，容易检测不到，先不加滤波*)
      IF (g_nAutoParalleType=0 AND g_fZAxisHeight > (g_fParalleBorderHeightM+g_fParalleZFollowHeightM) ) OR (g_nAutoParalleType=1 AND g_bAutoParalleInfraedSensor=FALSE) THEN
        g_boFindEage := true;(*给引脚赋true，让cnc收到寻边完成信号停止移动*)
        IF g_fAutoParalleDirectionM=0.0 THEN
          g_fYOverShootPosition := g_fCurrentCoordYBuffer;(*探到边纪录下当前Y轴坐标*)
        ELSIF g_fAutoParalleDirectionM=1.0 THEN
          g_fYOverShootPosition := g_fCurrentCoordYBuffer;(*探到边纪录下当前Y轴坐标*)
        ELSIF g_fAutoParalleDirectionM=2.0 THEN
          g_fYOverShootPosition := g_diXMachineCoordinate;(*探到边纪录下当前X轴坐标*)
        END_IF;
        g_bZFollowClose := TRUE;
        g_boCNCMoveDisable := TRUE;
        nMoveState :=15;
      END_IF;
    END_IF;

  15: (*等待随动关闭完成*)
    g_nFollowState :=101; 
    IF g_bZFollowOutDone THEN
      nMoveState := 0;
      g_bZFollowClose := FALSE;
      g_boCNCMoveDisable := FALSE;
      IF g_bOpenFollowDownLimitVel THEN
		g_ZFollowIn.DISABLENEGATIVE := FALSE;
      END_IF;
    END_IF;

END_CASE;

(*暂停情况下，并且当前CNC是运行的G38.2探针，PLC是运行探边*)
IF rTrigMovePause.Q AND (g_niMotionType = 5 OR  g_niMotionType = 2) AND (nMoveState =10 OR nPlcPauseState >= 40) THEN
  nPlcPauseState:=10;
  nMoveState :=0;
  bPauseZAxisState := FALSE;
  IF Axis_Z.NCTOPLC.AXISSTATE = 9 THEN
    bPauseZAxisState := TRUE;
  ELSE
    dPauseZAxisCoordinate := Axis_Z.NCTOPLC.ACTPOS;
    g_bZAbsExecute := FALSE;
  END_IF;
END_IF;
CASE nPlcPauseState OF
  0:
    nPlcPauseState := 0;
  10:(*关闭CNC运动使能，随动*)
    g_boCNCMoveDisable := TRUE;
    g_bZLiftExecute := FALSE;
    g_bZFollowExecute := FALSE;
    g_bZLiftingDone := FALSE;
    IF g_bOpenFollowDownLimitVel THEN
      g_ZFollowIn.DISABLENEGATIVE := FALSE;
    END_IF;
    IF Axis_Z.NCTOPLC.AXISSTATE = 2 THEN
      nPlcPauseState:= 20;
    END_IF;
  20:(*上抬*)(*该状态暂停，在上抬状态机中忽略暂停信号，会继续上抬直到完成*)
    g_bZLiftExecute := TRUE;
    IF g_bZLiftingDone THEN
      g_bZLiftExecute := FALSE;
      nPlcPauseState := 30;
    END_IF; 
  30:(*PLC开始，开随动*)(*该状态暂停，随动关闭，Z轴不上抬*)
    IF bCurState THEN
      IF bPauseZAxisState THEN
        g_bZFollowDone := FALSE;
        g_fZFollowHeight := g_fParalleZFollowHeightM;
		g_bZFollowExecute := TRUE;  
        nPlcPauseState := 40;
        IF g_bOpenFollowDownLimitVel THEN
			g_ZFollowIn.DISABLENEGATIVE := TRUE;
		END_IF;
      ELSE
        g_bZAbsDone := FALSE;
        g_fZAbsPosition := dPauseZAxisCoordinate;
        g_bZAbsExecute := TRUE;
        nPlcPauseState := 45;
      END_IF;
       g_boFindEage := FALSE;
    END_IF;
  40:(*等待随动到位*)
     (*用于监控随动报警卡在哪个状态机*)
    g_nFollowState :=1; 
    IF g_bZFollowDone THEN
      g_bZFollowExecute := FALSE;
      nPlcPauseState := 50;
      nMoveState :=10;
    END_IF;
  45:(*等待定高到位*)
    IF g_bZAbsDone THEN
     g_bZFollowExecute := FALSE;
      nPlcPauseState := 50;
      nMoveState :=10;
    END_IF;
  50:(*开启CNC运动使能*)
    g_boCNCMoveDisable := FALSE;
    nPlcPauseState := 0; 
END_CASE;

CASE nCloseParalleState OF
  0:
    nCloseParalleState := 0;
  10:
    IF nMoveState=0 THEN(*等待关随动完成*)
      g_boFindEage := FALSE;
      M.ENABLE[163] := 0;
      nCloseParalleState := 0;
    END_IF;
END_CASE;

CASE nCapacitorCheckState OF
  0:
    nCapacitorCheckState := 0;
  10:
    IF g_nAutoParalleType=0 AND g_fZAxisHeight < (g_fParalleBorderHeightM+g_fParalleZFollowHeightM) AND nMoveState <> 9 AND nMoveState <> 10
    AND g_fCurrentCoordYBuffer < g_fYOverShootPosition AND g_boFindEage THEN
      Ton_Alarm(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dAlarmTime)));
      IF Ton_Alarm.Q THEN 
        g_bEdgCapacitanceAlarm := TRUE;
        Ton_Alarm(IN := FALSE);
        nCapacitorCheckState := 0;
      END_IF;  
    END_IF; 
END_CASE;


IF g_bPlcResetBuffer THEN
  nMoveState := 0;
  nCloseParalleState := 0;
  nPlcPauseState := 0;
  nCapacitorCheckState := 0;
  nCapacitorCheckState_Pause := 0;
  g_bZFollowClose := FALSE;
  g_boFindEage := FALSE;
  Ton_Alarm(IN := FALSE);
  IF g_bOpenFollowDownLimitVel THEN
    g_ZFollowIn.DISABLENEGATIVE := FALSE;
  END_IF;
END_IF;

g_noPlcPauseState_AutoParalle := nPlcPauseState;

(*plc开始暂停状态*)
IF g_bPlcStartBuffer THEN
  bCurState := TRUE;
  nCapacitorCheckState := nCapacitorCheckState_Pause;
END_IF;
IF g_bPlcPauseBuffer THEN
  bCurState := FALSE;
  nCapacitorCheckState_Pause := nCapacitorCheckState;
  nCapacitorCheckState := 0;
END_IF;
